export type BlogLocale = 'en';
export const postsFor = (_locale: BlogLocale = 'en') => POSTS;
export const getPost = (slug: string, locale: BlogLocale = 'en') => postsFor(locale).find((p) => p.slug === slug);

/** newest first; posts of the same day keep the document's order (Array.prototype.sort is stable) */
export const byNewest = (a: BlogPost, b: BlogPost) => (a.datePublished < b.datePublished ? 1 : a.datePublished > b.datePublished ? -1 : 0);

/** two related posts: the next two in listing order, wrapping around */
export const relatedPosts = (slug: string, locale: BlogLocale = 'en') => {
  const list = [...postsFor(locale)].sort(byNewest);
  const i = list.findIndex((p) => p.slug === slug);
  if (i < 0 || list.length < 2) return list.filter((p) => p.slug !== slug).slice(0, 2);
  const out: BlogPost[] = [];
  for (let k = 1; k < list.length && out.length < 2; k++) out.push(list[(i + k) % list.length]);
  return out;
};

/** a section's content as ordered blocks (`paragraphs` + `table` for sections written before blocks existed) */
export const sectionBlocks = (s: BlogSection): BlogBlock[] =>
  s.blocks ?? [...(s.paragraphs ?? []).map((p) => ({ p })), ...(s.table ? [{ table: s.table }] : [])];

const stripInline = (t: string) => t.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').replace(/\*\*([^*]+)\*\*/g, '$1').replace(/_([^_]+)_/g, '$1');
/** the article's words (headings, paragraphs, lists, table cells, FAQ) — BlogPosting.wordCount and the read time */
export const wordCountOf = (post: BlogPost) => {
  const parts: string[] = [];
  for (const s of post.sections) {
    if (s.heading) parts.push(s.heading);
    for (const b of sectionBlocks(s)) {
      if ('p' in b) parts.push(b.p);
      else if ('h3' in b) parts.push(b.h3);
      else if ('list' in b) parts.push(...b.list.items);
      else parts.push(...b.table.head, ...b.table.rows.flat());
    }
  }
  for (const f of post.faqs) parts.push(f.question, f.answer);
  return parts.map(stripInline).join(' ').split(/\s+/).filter(Boolean).length;
};
/** "N min read" at about 200 words a minute (the client supplied no read times) */
export const readTimeOf = (post: BlogPost) => post.readTime || `${Math.max(1, Math.round(wordCountOf(post) / 200))} min read`;
